class _Output:
    def __init__(self, stream, quiet: bool = False, verbose: bool = False):
        self.stream = stream
        self.quiet = quiet
        self.verbose = verbose
        self._lock = threading.Lock()

    def info(self, message: str = "") -> None:
        if self.quiet:
            return
        with self._lock:
            print(message, file=self.stream, flush=True)

    def detail(self, message: str = "") -> None:
        if self.quiet or not self.verbose:
            return
        with self._lock:
            print(message, file=self.stream, flush=True)

    def warn(self, message: str) -> None:
        with self._lock:
            print(f"warning: {message}", file=sys.stderr, flush=True)

    def error(self, message: str) -> None:
        with self._lock:
            print(f"error: {message}", file=sys.stderr, flush=True)


def _root() -> Path:
    return Path.cwd()


def _pytorch_dir() -> Path:
    return _root() / "YoloModels" / "pytorch"


def _find_config_path() -> Path | None:
    config_dir = _root() / "Config"
    if not config_dir.exists():
        return None
    files = sorted(config_dir.rglob("*.json"))
    if not files:
        return None
    non_default = [path for path in files if path.name != "config.json"]
    return non_default[0] if non_default else files[0]


def _resolve_path(value: str | Path) -> Path:
    path = Path(value).expanduser()
    if not path.is_absolute():
        path = _root() / path
    return path.resolve()


def _rel_posix(path: Path) -> str:
    try:
        return path.resolve().relative_to(_root().resolve()).as_posix()
    except ValueError:
        return str(path)


def _path_size(path: Path) -> int:
    try:
        if path.is_dir():
            return sum(p.stat().st_size for p in path.rglob("*") if p.is_file())
        return path.stat().st_size
    except OSError:
        return 0


def _format_mb(size_bytes: int) -> str:
    return f"{size_bytes / (1024 ** 2):.1f} MB"


def _newest_mtime(path: Path) -> float:
    try:
        if path.is_file():
            return path.stat().st_mtime
        times = [p.stat().st_mtime for p in path.rglob("*") if p.is_file()]
        return max(times) if times else path.stat().st_mtime
    except OSError:
        return 0.0


def _parse_input_size(value: str) -> tuple[int, int]:
    text = str(value).strip().lower().replace(" ", "")
    try:
        if "x" in text:
            width, height = text.split("x", 1)
            size = (int(width), int(height))
        else:
            size = (int(text), int(text))
    except ValueError as exc:
        raise _SelectionError(f"invalid --input-size {value!r} (use N or WxH)") from exc
    if size[0] <= 0 or size[1] <= 0:
        raise _SelectionError(f"invalid --input-size {value!r} (must be positive)")
    return size


def _meta_input_size(meta: dict) -> tuple[int, int] | None:
    raw = meta.get("input_size")
    if isinstance(raw, (list, tuple)) and raw:
        try:
            if len(raw) > 1:
                return int(raw[0]), int(raw[1])
            return int(raw[0]), int(raw[0])
        except (TypeError, ValueError):
            return None
    if isinstance(raw, int) and raw > 0:
        return raw, raw
    return None


# ---------------------------------------------------------------------------
# Logging (boot's quiet-logging approach, copied so boot.py stays out of this
# CLI's import chain)
# ---------------------------------------------------------------------------


def _configure_quiet_logging(
    *,
    verbose: bool = False,
    quiet: bool = False,
    stream=None,
) -> None:
    root = logging.getLogger()
    for handler in list(root.handlers):
        try:
            root.removeHandler(handler)
            handler.flush()
            handler.close()
        except Exception:
            pass

    root.setLevel(logging.INFO)
    root.propagate = False

    class _iSpyLogFilter(logging.Filter):
        def filter(self, record: logging.LogRecord) -> bool:
            name = record.name or ""
            return name == "root" or name == "__main__" or name.startswith("iSpy")

    formatter = logging.Formatter("%(asctime)s [%(name)s] %(levelname)s: %(message)s")

    if not quiet:
        stream_handler = logging.StreamHandler(stream or sys.stdout)
        stream_handler.setLevel(logging.DEBUG if verbose else logging.INFO)
        stream_handler.setFormatter(formatter)
        stream_handler.addFilter(_iSpyLogFilter())
        root.addHandler(stream_handler)

    log_path = _root() / "Outputs" / "log.txt"
    log_path.parent.mkdir(parents=True, exist_ok=True)
    file_handler = logging.FileHandler(log_path, mode="a", encoding="utf-8")
    file_handler.setLevel(logging.DEBUG if verbose else logging.INFO)
    file_handler.setFormatter(formatter)
    file_handler.addFilter(_iSpyLogFilter())
    root.addHandler(file_handler)

    logging.getLogger("iSpy").setLevel(logging.DEBUG if verbose else logging.INFO)
    for name in list(logging.Logger.manager.loggerDict):
        if name != "__main__" and not name.startswith("iSpy"):
            logging.getLogger(name).setLevel(logging.WARNING)


@contextlib.contextmanager
def _worker_output(enabled: bool):
    # optimizer prints worker stdout/stderr through module-level handles so
    # boot can bind the real console before sys.stdout is swapped.  The CLI
    # hides that output unless -v so quiet/json modes stay clean.
    if enabled:
        yield
        return
    from iSpy.vision import optimizer

    old_out, old_err = optimizer._REAL_STDOUT, optimizer._REAL_STDERR
    optimizer._REAL_STDOUT = _NullWriter()
    optimizer._REAL_STDERR = _NullWriter()
    try:
        yield
    finally:
        optimizer._REAL_STDOUT, optimizer._REAL_STDERR = old_out, old_err


# ---------------------------------------------------------------------------
# Model discovery
# ---------------------------------------------------------------------------


def _fingerprint(path: Path) -> tuple[int, str]:
    from iSpy.validations.benchmarking import _file_fingerprint

    return _file_fingerprint(path)


def _dedupe_paths(paths) -> list[Path]:
    seen: set[tuple[int, str]] = set()
    unique: list[Path] = []
    for path in paths:
        path = path.resolve()
        try:
            fingerprint = _fingerprint(path)
        except OSError:
            continue
        if fingerprint in seen:
            continue
        seen.add(fingerprint)
        unique.append(path)
    return unique


def _matches_excludes(path: Path, excludes: list[str]) -> bool:
    name = path.name
    stem = path.stem
    return any(
        fnmatch.fnmatch(name, pattern) or fnmatch.fnmatch(stem, pattern)
        for pattern in excludes
    )


def _discover_all(
    excludes: list[str] | None = None,
    skip_defaults: bool = False,
) -> list[Path]:
    """Every .pt directly in YoloModels/pytorch, minus world/ and *.part."""
    excludes = excludes or []
    pytorch = _pytorch_dir()
    if not pytorch.is_dir():
        return []
    found = []
    for path in sorted(pytorch.glob("*.pt")):
        if path.name.endswith(".part"):
            continue
        if skip_defaults and path.name.startswith("_default_"):
            continue
        if _matches_excludes(path, excludes):
            continue
        found.append(path)
    return _dedupe_paths(found)


def _resolve_model_spec(spec: str, excludes: list[str], skip_defaults: bool) -> list[Path]:
    pytorch = _pytorch_dir()
    text = str(spec).strip()
    if not text:
        return []

    candidates: list[Path] = []
    if any(char in text for char in "*?["):
        if Path(text).is_absolute():
            patterns = [text]
        else:
            patterns = [str(pytorch / text), str(_root() / text), text]
        for pattern in patterns:
            for match in glob.glob(pattern, recursive=True):
                candidates.append(Path(match))
    else:
        path = Path(text).expanduser()
        if path.is_absolute():
            candidates.append(path)
        else:
            candidates.extend(
                [
                    _root() / path,
                    pytorch / path,
                    pytorch / f"{text}.pt",
                    _root() / f"{text}.pt",
                ]
            )

    found = []
    for candidate in candidates:
        if candidate.is_file() and candidate.suffix.lower() == ".pt":
            if skip_defaults and candidate.name.startswith("_default_"):
                continue
            if _matches_excludes(candidate, excludes):
                continue
            found.append(candidate.resolve())
    return _dedupe_paths(found)


def _load_model_meta(path: Path) -> dict:
    from iSpy.vision.metadata import read_metadata

    try:
        return read_metadata(path) or {}
    except Exception:
        return {}


def _model_info(path: Path, meta: dict | None = None) -> ModelInfo:
    meta = dict(meta if meta is not None else _load_model_meta(path))
    info = ModelInfo(path=path, meta=meta)
    info.task = str(meta.get("task") or "detect")
    try:
        info.nc = int(meta.get("nc") or meta.get("num_classes") or 0)
    except (TypeError, ValueError):
        info.nc = 0
    info.input_size = _meta_input_size(meta) or (640, 640)
    try:
        info.size_bytes = path.stat().st_size
    except OSError:
        info.size_bytes = 0
    return info


def _ensure_sidecar(info: ModelInfo) -> bool:
    """Generate the _metadata.yaml sidecar exactly like boot.setup_files."""
    from iSpy.vision.metadata import (
        metadata_from_pt,
        metadata_path_for,
        read_metadata,
        write_metadata,
    )

    sidecar = metadata_path_for(info.path)
    if sidecar.exists():
        meta = read_metadata(info.path)
        if meta:
            info.meta = meta
            info.meta_error = ""
            return True
    try:
        meta = metadata_from_pt(info.path, trusted=True)
        write_metadata(sidecar, meta)
    except Exception as exc:
        info.meta_error = f"could not read/generate model metadata: {exc}"
        return False
    info.meta = meta or {}
    info.meta_error = ""
    info.task = str(info.meta.get("task") or "detect")
    try:
        info.nc = int(info.meta.get("nc") or info.meta.get("num_classes") or 0)
    except (TypeError, ValueError):
        info.nc = 0
    info.input_size = _meta_input_size(info.meta) or info.input_size
    return True


# ---------------------------------------------------------------------------
# Camera config helpers
# ---------------------------------------------------------------------------


def _load_config():
    path = _find_config_path()
    if path is None:
        return None
    from iSpy.config.iSpyConfig import iSpyConfig

    return iSpyConfig(str(path), create=False)


def _camera_uses(config) -> list[tuple[str, Path, dict]]:
    from iSpy.config.iSpyConfig import get_pipeline_settings

    uses: list[tuple[str, Path, dict]] = []
    if config is None:
        return uses
    cameras = config.get_nested("camera_configs", default={}) or {}
    for name, camera in cameras.items():
        if not isinstance(camera, dict):
            continue
        settings = get_pipeline_settings(camera) or {}
        vision_model = settings.get("vision_model")
        if not isinstance(vision_model, dict):
            continue
        source = vision_model.get("source_pt") or vision_model.get("file_path")
        if not source or not str(source).lower().endswith(".pt"):
            continue
        path = _resolve_path(str(source))
        if not path.is_file():
            continue
        uses.append((str(name), path, settings))
    return uses


def _selection(args, config) -> list[_ModelUse]:
    excludes = args.excludes or []
    skip_defaults = bool(args.skip_defaults)
    selected: list[_ModelUse] = []

    if args.all:
        for path in _discover_all(excludes, skip_defaults):
            selected.append(_ModelUse(_model_info(path)))

    for spec in args.models or []:
        matches = _resolve_model_spec(spec, excludes, skip_defaults)
        if not matches:
            raise _SelectionError(f"no .pt model matched {spec!r}")
        for path in matches:
            selected.append(_ModelUse(_model_info(path)))

    if args.camera or args.configured:
        if config is None:
            raise _SelectionError(
                "--camera/--configured need Config/config.json, which was not found"
            )
        uses = _camera_uses(config)
        known = {name for name, _path, _settings in uses}
        if args.camera:
            unknown = [name for name in args.camera if name not in known]
            if unknown:
                raise _SelectionError(
                    "unknown camera(s): "
                    + ", ".join(unknown)
                    + (" (configured: " + ", ".join(sorted(known)) + ")" if known else "")
                )
            wanted = set(args.camera)
            uses = [use for use in uses if use[0] in wanted]
        for name, path, settings in uses:
            if skip_defaults and path.name.startswith("_default_"):
                continue
            if _matches_excludes(path, excludes):
                continue
            selected.append(
                _ModelUse(_model_info(path), camera=name, settings=settings)
            )

    deduped: dict[tuple[str, str | None], _ModelUse] = {}
    for use in selected:
        deduped.setdefault((str(use.model.path), use.camera), use)
    return list(deduped.values())


# ---------------------------------------------------------------------------
# Format resolution
# ---------------------------------------------------------------------------


def _supported_formats() -> tuple[str, ...]:
    from iSpy.vision.pipelines.optimizable import SUPPORTED_TARGET_FORMATS

    return SUPPORTED_TARGET_FORMATS


def _recommended_format() -> str:
    try:
        from iSpy.config.AutoOpt import recommend_format

        fmt = recommend_format(ignore_dependencies=True, runtime_supported=False)
        if fmt == "tflite" and not exporter_supported("tflite"):
            # Auto-opt can recommend tflite for inference on ARM, but this
            # box cannot build a new .tflite (LiteRT is x86_64/macOS only).
            logger.info(
                "TFLite export is unavailable on this platform - building ONNX instead."
            )
            return "onnx"
        return fmt
    except Exception:
        logger.warning(
            "AutoOpt.recommend_format did not work for this device - falling back to onnx"
        )
        return "onnx"


def _module_installed(name: str) -> bool:
    import importlib.util

    try:
        return importlib.util.find_spec(name) is not None
    except Exception:
        return False


def _rknn_env_ready() -> bool:
    try:
        from iSpy.boot._rknn_converter_env import converter_env_status

        return bool(converter_env_status().get("current"))
    except Exception:
        return False


def _all_formats() -> list[str]:
    """Every backend this machine can build/run - same gates as ispy-bench."""
    from iSpy.config import AutoOpt

    formats = ["onnx"]
    if AutoOpt.has_rockchip_npu() or _rknn_env_ready():
        formats.append("rknn")
    if AutoOpt.has_nvidia() and AutoOpt.has_tensorrt():
        formats.append("engine")
    if (
        AutoOpt.has_intel_gpu()
        or AutoOpt.has_intel_vpu()
        or _module_installed("openvino")
    ):
        formats.append("openvino")
    if AutoOpt.has_qualcomm_npu():
        formats.append("qnn")
    if (
        (AutoOpt.has_arm() and not AutoOpt.has_nvidia())
        or AutoOpt.has_edge_tpu()
    ) and exporter_supported("tflite"):
        formats.append("tflite")
    if AutoOpt.has_tpu():
        formats.append("tpu")
    # hailo/coreml are deliberately never prospected - both need a vendor
    # toolchain/runtime GenericYolo may not be able to load on this host.
    return formats


def _resolve_formats(args) -> tuple[list[str], bool]:
    """Return (resolved_formats, explicit) where explicit means user passed --format or --all-formats."""
    requested: list[str] = []
    explicit = False
    if args.all_formats:
        requested.extend(_all_formats())
        explicit = True
    for value in args.formats or []:
        requested.extend(
            part.strip().lower() for part in str(value).split(",") if part.strip()
        )
        explicit = True
    if not requested:
        requested = ["auto"]

    supported = set(_supported_formats())
    resolved: list[str] = []
    for fmt in requested:
        if fmt == "auto":
            fmt = _recommended_format().strip().lower()
            if fmt not in supported:
                fmt = "onnx"
        if fmt not in supported:
            raise _SelectionError(
                f"unsupported format {fmt!r} (choose from: auto, "
                + ", ".join(sorted(supported))
                + ")"
            )
        if fmt not in resolved:
            resolved.append(fmt)
    return resolved, explicit


def _default_quantize(fmt: str) -> bool:
    # rknn/tflite are the int8-by-default pipelines.  hailo compile is always
    # int8 as well (optimizer._convert_hailo defaults quantize=True), so its
    # sidecar has to say so too.
    return fmt in _DEFAULT_INT8


def _guard_reason(fmt: str, task: str, input_size: tuple[int, int]) -> str:
    if fmt == "hailo":
        if task != "detect":
            return f"hailo compile supports detect only (model task is {task})"
        if tuple(input_size) != (640, 640):
            return "hailo compile is hard-wired to 640x640"
    if fmt == "qnn" and task != "detect":
        return f"qnn supports detect only (model task is {task})"
    return ""


# ---------------------------------------------------------------------------
# Artifact paths / freshness
# ---------------------------------------------------------------------------


def _artifact_path(source: Path, fmt: str) -> Path:
    from iSpy.vision import optimizer

    return optimizer._format_output_dir(fmt) / optimizer._artifact_name(source, fmt)


def _desired_path(source: Path, fmt: str) -> Path:
    from iSpy.vision import optimizer

    return optimizer._desired_output_path(source, fmt)


def _stored_quantize(artifact: Path) -> bool | None:
    from iSpy.vision.metadata import read_metadata

    meta = read_metadata(artifact) or {}
    stored = meta.get("quantize")
    if stored is None:
        quantization = meta.get("quantization")
        stored = (quantization != "none") if quantization is not None else None
    return bool(stored) if stored is not None else None


def _freshness(source: Path, fmt: str, quantize: bool, artifact: Path) -> tuple[bool, str]:
    if not artifact.exists():
        return False, "artifact missing"
    try:
        source_mtime = source.stat().st_mtime
    except OSError:
        return False, "source model is missing"
    artifact_mtime = _newest_mtime(artifact)
    if artifact_mtime < source_mtime:
        return False, "artifact older than its source .pt"
    if fmt in ("rknn", "onnx"):
        stored = _stored_quantize(artifact)
        if stored is None:
            return False, "metadata sidecar missing or has no quantize flag"
        if stored != bool(quantize):
            return False, f"artifact quantize={stored} but {quantize} was requested"
    return True, "up to date"


# ---------------------------------------------------------------------------
# Planning
# ---------------------------------------------------------------------------


def _preview_dataset(args, settings: dict, fmt: str) -> str:
    if args.calib_dataset:
        return str(args.calib_dataset)
    camera_dataset = settings.get("quantization_dataset")
    if camera_dataset:
        return str(camera_dataset)
    try:
        from iSpy.validations.benchmarking import _MIN_REAL_IMAGES, _PROJECT_ROOT

        root = _PROJECT_ROOT / "QuantizeDataset"
        if root.is_dir():
            for candidate in sorted(root.iterdir()):
                if not candidate.is_dir() or candidate.name in ("default", "valid", "Trash"):
                    continue
                count = sum(
                    1
                    for path in candidate.rglob("*")
                    if path.is_file()
                    and path.suffix.lower() in (".jpg", ".jpeg", ".png", ".bmp")
                )
                if count >= _MIN_REAL_IMAGES:
                    return candidate.name
    except Exception:
        pass
    return "synthetic" if fmt in _INT8_FORMATS else "-"


def _plan_jobs(
    uses: list[_ModelUse],
    formats: list[str],
    args,
    explicit_formats: bool = False,
) -> list[Job]:
    jobs: list[Job] = []
    offline = network_policy.is_offline()

    for use in uses:
        info = use.model
        settings = use.settings or {}
        for fmt in formats:
            # if user didn't specify --format/--all-formats, use camera's target_format
            if not explicit_formats and use.camera and settings.get("target_format"):
                cam_fmt = str(settings["target_format"]).strip().lower()
                if cam_fmt != "auto" and cam_fmt != fmt:
                    continue  # this job's fmt doesn't match camera's preference
                fmt = cam_fmt

            quantize = (
                args.quantize
                if args.quantize is not None
                else (
                    bool(settings["quantize"])
                    if "quantize" in settings
                    else _default_quantize(fmt)
                )
            )
            if quantize and fmt not in _QUANTIZABLE:
                # warning, not an error - the artifact is still useful
                quantize = False

            input_size = None
            input_explicit = False
            if args.input_size:
                input_size = args.input_size
                input_explicit = True
            elif settings.get("input_size"):
                try:
                    input_size = _parse_input_size(str(settings["input_size"]))
                except _SelectionError:
                    input_size = None
            if input_size is None:
                input_size = info.input_size

            dataset_arg = args.calib_dataset
            if not dataset_arg and settings.get("quantization_dataset"):
                dataset_arg = str(settings["quantization_dataset"])

            job = Job(
                model=info,
                fmt=fmt,
                quantize=quantize,
                input_size=tuple(input_size),
                dataset_arg=dataset_arg,
                camera=use.camera or "",
                input_explicit=input_explicit,
            )

            reason = _guard_reason(fmt, info.task, job.input_size)
            if reason:
                job.action = "unsupported"
                job.reason = reason
                jobs.append(job)
                continue

            if fmt == "tpu":
                job.action = "passthrough"
                job.reason = "runs .pt via torch_xla"
                jobs.append(job)
                continue

            artifact = _artifact_path(info.path, fmt)
            if not args.force:
                fresh, detail = _freshness(info.path, fmt, quantize, artifact)
                if fresh:
                    job.action = "fresh"
                    job.reason = detail
                    job.artifact = artifact
                    job.size_bytes = _path_size(artifact)
                    jobs.append(job)
                    continue

                if fmt in ("rknn", "onnx") and not artifact.exists():
                    detail = "artifact missing"
                job.reason = detail

            if offline:
                reason = _offline_reason(fmt, quantize)
                if reason:
                    job.action = "offline"
                    job.reason = reason
                    jobs.append(job)
                    continue

            job.action = "build"
            if job.quantize:
                job.dataset_label = _preview_dataset(args, settings, fmt)
            jobs.append(job)

    return jobs


def _offline_reason(fmt: str, quantize: bool) -> str:
    """Pre-flight an offline build: any pip/download need means skip."""
    try:
        from iSpy.boot.converter_envs import converter_env_status, needs_env
        from iSpy.vision.optimizer import _missing_build_modules
        from iSpy.vision.pipelines.optimizable import offline_build_requirements
    except Exception:
        return ""

    settings = {"optimize": True, "quantize": bool(quantize), "target_format": fmt}
    try:
        requirements = offline_build_requirements(settings)
    except Exception:
        requirements = []
    if requirements:
        return "; ".join(f"{req.name}: {req.reason}" for req in requirements)

    try:
        if needs_env(fmt):
            status = converter_env_status(fmt)
            if not status.get("current"):
                return (
                    f"{fmt} converter environment is not provisioned - "
                    "building it needs pip downloads"
                )
        elif fmt != "tpu":
            missing = _missing_build_modules(fmt)
            if missing:
                return (
                    "missing build dependencies offline: " + ", ".join(missing)
                )
    except Exception:
        pass
    return ""


# ---------------------------------------------------------------------------
# Locks / backups / child cleanup
# ---------------------------------------------------------------------------


def _artifact_lock(artifact: Path):
    from iSpy.boot.converter_envs import _build_lock

    lock_dir = _root() / "Outputs" / "optimize_locks"
    lock_dir.mkdir(parents=True, exist_ok=True)
    key = hashlib.sha256(str(artifact.resolve()).encode("utf-8")).hexdigest()[:16]
    return _build_lock(lock_dir / f"{key}.lock", timeout=600.0, label="optimize")


def _backup_artifact(artifact: Path) -> Path | None:
    from iSpy.vision.metadata import metadata_path_for

    if not artifact.exists():
        return None
    key = hashlib.sha256(str(artifact.resolve()).encode("utf-8")).hexdigest()[:16]
    backup_dir = _root() / "Outputs" / "optimize_backup" / key
    if backup_dir.exists():
        shutil.rmtree(backup_dir, ignore_errors=True)
    backup_dir.mkdir(parents=True, exist_ok=True)
    shutil.move(str(artifact), str(backup_dir / artifact.name))
    sidecar = metadata_path_for(artifact)
    if sidecar.exists():
        shutil.move(str(sidecar), str(backup_dir / sidecar.name))
    return backup_dir


def _restore_artifact(backup_dir: Path | None, artifact: Path) -> None:
    from iSpy.vision.metadata import metadata_path_for

    if artifact.exists():
        if artifact.is_dir():
            shutil.rmtree(artifact, ignore_errors=True)
        else:
            try:
                artifact.unlink()
            except OSError:
                pass
    if backup_dir is None or not backup_dir.is_dir():
        return
    for entry in backup_dir.iterdir():
        shutil.move(str(entry), str(artifact.parent / entry.name))
    shutil.rmtree(backup_dir, ignore_errors=True)
    sidecar = metadata_path_for(artifact)
    if not sidecar.exists() and not artifact.exists():
        logger.warning("Could not restore the previous artifact for %s", artifact)


def _discard_backup(backup_dir: Path | None) -> None:
    if backup_dir is not None:
        shutil.rmtree(backup_dir, ignore_errors=True)


def _cleanup_partials(since: float) -> None:
    roots = [_root() / "YoloModels", _root() / "Outputs"]
    for base in roots:
        if not base.is_dir():
            continue
        for path in base.rglob("*.part"):
            try:
                if path.stat().st_mtime >= since:
                    path.unlink()
            except OSError:
                pass


def _terminate_conversion_children() -> None:
    # the converter wrapper owns the child; when it ignores a timeout (or the
    # user hits Ctrl-C) find `iSpy.boot._convert_worker` processes and kill
    # them before reporting, otherwise the board keeps building in the dark
    try:
        import psutil
    except Exception:
        return
    victims = []
    try:
        for child in psutil.Process().children(recursive=True):
            try:
                cmdline = " ".join(child.cmdline())
            except Exception:
                continue
            if "_convert_worker" in cmdline:
                victims.append(child)
    except Exception:
        return
    for child in victims:
        try:
            child.terminate()
        except Exception:
            pass
    if victims:
        try:
            _gone, alive = psutil.wait_procs(victims, timeout=5)
        except Exception:
            alive = []
        for child in alive:
            try:
                child.kill()
            except Exception:
                pass


# ---------------------------------------------------------------------------
# Conversion execution
# ---------------------------------------------------------------------------


def _call_converter(job: Job, timeout: float | None):
    from iSpy.vision.optimizer import _convert_model_subprocess_report

    kwargs = {
        "model_file": str(job.model.path),
        "target_format": job.fmt,
        "input_size": list(job.input_size),
        "quantize": job.quantize,
        "force": True,
        "dataset_path": str(job.dataset) if job.dataset else None,
    }
    if not timeout:
        return _convert_model_subprocess_report(**kwargs)

    pool = concurrent.futures.ThreadPoolExecutor(max_workers=1)
    try:
        future = pool.submit(_convert_model_subprocess_report, **kwargs)
        return future.result(timeout=timeout)
    except concurrent.futures.TimeoutError:
        _terminate_conversion_children()
        return (
            job.model.path,
            {
                "status": "terminated",
                "error": f"conversion timed out after {timeout:g}s",
            },
        )
    finally:
        pool.shutdown(wait=False, cancel_futures=True)


def _resolve_dataset(job: Job, out: _Output) -> bool:
    if not job.quantize:
        return True
    if job.fmt not in _INT8_FORMATS:
        return True

    from iSpy.validations.benchmarking import _real_calibration_dataset

    if job.dataset_arg:
        try:
            dataset = _real_calibration_dataset(job.dataset_arg)
        except SystemExit:
            out.warn(
                f"calibration dataset {job.dataset_arg!r} has no images - "
                "falling back to a real/auto dataset"
            )
            dataset = None
        if dataset is not None:
            job.dataset = dataset
            job.dataset_label = dataset.name
            return True

    dataset = _real_calibration_dataset()
    if dataset is not None:
        job.dataset = dataset
        job.dataset_label = dataset.name
        return True

    out.warn(
        f"no real calibration images for int8 {job.fmt} - falling back to "
        "SYNTHETIC NOISE in QuantizeDataset/default. Quantization quality will "
        "be poor; pass --calib-dataset or add a QuantizeDataset/<name> folder."
    )
    try:
        from iSpy.dataset.dataset import calib_count_for_format, prepare_quantization_dataset
        from iSpy.vision.optimizer import default_quantization_dataset_dir

        dataset = default_quantization_dataset_dir()
        prepare_quantization_dataset(
            str(dataset), count=calib_count_for_format(job.fmt)
        )
    except Exception as exc:
        job.status = "FAILED"
        job.error_status = "conversion"
        job.error = f"could not prepare a synthetic calibration dataset: {exc}"
        return False
    job.dataset = dataset
    job.dataset_label = "synthetic"
    return True


def _verify_artifact(job: Job) -> None:
    import numpy as np

    from iSpy.vision.genericYolo import GenericYolo
    from iSpy.vision.ModelInspector import fill_missing_config

    height, width = int(job.input_size[1]), int(job.input_size[0])
    config = {
        "file_path": str(job.artifact),
        "source_pt": str(job.model.path),
        "task": job.model.task or "detect",
        "nc": job.model.nc,
        "input_size": [width, height],
        "device": 0 if job.fmt == "engine" else "cpu",
        "batch_size": 1,
        "min_conf": 0.25,
    }
    model = GenericYolo(fill_missing_config(config))
    try:
        frame = np.zeros((height, width, 3), dtype=np.uint8)
        model.predict(frame)
    finally:
        release = getattr(model, "release", None)
        if callable(release):
            try:
                release()
            except Exception:
                pass


def _remove_artifact(job: Job) -> None:
    from iSpy.vision.metadata import metadata_path_for

    if job.artifact is None:
        return
    artifact = job.artifact
    if artifact.is_dir():
        shutil.rmtree(artifact, ignore_errors=True)
    else:
        try:
            artifact.unlink()
        except OSError:
            pass
    sidecar = metadata_path_for(artifact)
    try:
        sidecar.unlink()
    except OSError:
        pass


def _build_job(job: Job, args, out: _Output) -> Job:
    started = time.time()
    job.artifact = _desired_path(job.model.path, job.fmt)
    backup = None
    try:
        if not _ensure_sidecar(job.model):
            job.status = "FAILED"
            job.error_status = "conversion"
            job.error = job.model.meta_error
            return job
        # re-check guard rails now that the sidecar is authoritative
        reason = _guard_reason(job.fmt, job.model.task, job.input_size)
        if reason:
            job.action = "unsupported"
            job.status = "SKIPPED"
            job.reason = reason
            return job
        if not args.force:
            fresh, detail = _freshness(
                job.model.path, job.fmt, job.quantize, job.artifact
            )
            if fresh:
                job.action = "fresh"
                job.status = "SKIPPED"
                job.reason = detail
                job.size_bytes = _path_size(job.artifact)
                return job
        if not _resolve_dataset(job, out):
            return job

        with _artifact_lock(job.artifact):
            backup = _backup_artifact(job.artifact)
            result, report = _call_converter(job, args.timeout)
            if report is not None:
                _restore_artifact(backup, job.artifact)
                backup = None
                job.status = "FAILED"
                job.error_status = str(report.get("status") or "conversion")
                job.error = str(report.get("error") or "conversion failed")
                return job

            result_path = Path(result)
            if (
                result_path == job.model.path
                or not result_path.exists()
                or result_path.suffix.lower() == ".pt"
            ):
                _restore_artifact(backup, job.artifact)
                backup = None
                job.status = "FAILED"
                job.error_status = "conversion"
                job.error = "conversion produced no artifact (worker fell back to the .pt)"
                return job

            job.artifact = result_path
            job.size_bytes = _path_size(result_path)
            _discard_backup(backup)
            backup = None

        job.status = "OK"
        return job
    except KeyboardInterrupt:
        _restore_artifact(backup, job.artifact)
        _cleanup_partials(started)
        raise
    except Exception as exc:
        _restore_artifact(backup, job.artifact)
        _cleanup_partials(started)
        job.status = "FAILED"
        job.error_status = "conversion"
        job.error = str(exc)
        return job
    finally:
        job.seconds = time.time() - started
        if job.status in _BAD_STATUSES:
            _cleanup_partials(started)


def _execute_job(job: Job, args, out: _Output) -> Job:
    if job.action == "fresh":
        job.status = "SKIPPED"
        return job
    if job.action in ("unsupported", "offline"):
        job.status = "SKIPPED"
        return job
    if job.action == "passthrough":
        job.status = "OK"
        job.verify = "n/a"
        return job

    job = _build_job(job, args, out)

    if job.status == "OK" and args.verify:
        try:
            _verify_artifact(job)
        except Exception as exc:
            job.status = "VERIFY_FAILED"
            job.verify = "FAILED"
            job.error_status = "verify"
            job.error = f"artifact failed to load/predict: {exc}"
            if args.remove_bad:
                _remove_artifact(job)
                job.error += " (artifact removed)"
        else:
            job.verify = "OK"
    elif job.status == "OK":
        job.verify = "skipped"
    return job


# ---------------------------------------------------------------------------
# Post-build actions
# ---------------------------------------------------------------------------


def _read_compare_report(source: Path, artifact: Path) -> dict | None:
    path = _root() / "Outputs" / "optimized_model_report.json"
    if not path.exists():
        return None
    try:
        ledger = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None
    entries = ledger.get("models") if isinstance(ledger, dict) else ledger
    if not isinstance(entries, list):
        return None
    source_str = str(source)
    artifact_str = str(artifact)
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        if entry.get("base_model") != source_str:
            continue
        optimized = str(entry.get("optimized_model") or "")
        if optimized == artifact_str or Path(optimized).name == artifact.name:
            return entry
    return None


def _attach_compare(jobs: list[Job]) -> None:
    for job in jobs:
        if job.status != "OK" or job.artifact is None:
            continue
        entry = _read_compare_report(job.model.path, job.artifact)
        if entry is None:
            job.compare = "unavailable"
            continue
        job.compare = str(entry.get("overall_verdict") or "UNKNOWN")
        speed = entry.get("speed") or {}
        try:
            job.speedup = float(speed.get("speedup")) if speed.get("speedup") else None
        except (TypeError, ValueError):
            job.speedup = None


def _bench_job(job: Job) -> None:
    if job.status != "OK" or job.artifact is None:
        return
    try:
        from iSpy.validations.benchmarking import benchmark
        from iSpy.vision.ModelInspector import fill_missing_config

        device = 0 if job.fmt == "engine" else "cpu"
        config = fill_missing_config(
            {
                "file_path": str(job.artifact),
                "source_pt": str(job.model.path),
                "task": job.model.task or "detect",
                "input_size": [int(job.input_size[0]), int(job.input_size[1])],
                "device": device,
                "batch_size": 1,
                "min_conf": 0.25,
            }
        )
        result = benchmark(
            config,
            0 if job.fmt == "rknn" else None,
            duration=2.0,
        )
        job.bench_fps = float(result.get("fps")) if result.get("fps") else None
    except Exception as exc:
        job.bench_error = str(exc)


def _apply_results(jobs: list[Job], config, selected_cameras: list[str]) -> list[str]:
    from iSpy.config.iSpyConfig import get_pipeline_settings
    from iSpy.vision.metadata import metadata_path_for

    if config is None:
        return []
    updated: list[str] = []
    cameras = config.get_nested("camera_configs", default={}) or {}
    selected = set(selected_cameras or [])

    for job in jobs:
        if job.status != "OK" or job.artifact is None:
            continue
        if not job.artifact.exists():
            continue
        for name, camera in cameras.items():
            if not isinstance(camera, dict):
                continue
            settings = get_pipeline_settings(camera) or {}
            vision_model = settings.get("vision_model")
            if not isinstance(vision_model, dict):
                continue
            if job.camera:
                if name != job.camera:
                    continue
            else:
                source = vision_model.get("source_pt") or vision_model.get("file_path")
                if not source or not str(source).lower().endswith(".pt"):
                    continue
                if _resolve_path(str(source)) != job.model.path:
                    continue
            if name in selected and job.camera and name != job.camera:
                # named camera, but this artifact was built for another model
                continue

            vision_model["source_pt"] = _rel_posix(job.model.path)
            vision_model["file_path"] = _rel_posix(job.artifact)
            settings["optimize"] = "auto"
            settings["target_format"] = job.fmt
            settings["quantize"] = bool(job.quantize)
            if metadata_path_for(job.artifact).exists():
                settings["quantization_dataset"] = settings.get(
                    "quantization_dataset", ""
                )
            updated.append(str(name))

    if updated:
        config.save()
    return sorted(set(updated))


# ---------------------------------------------------------------------------
# Introspection / clean
# ---------------------------------------------------------------------------


def _list_formats(args) -> list[str]:
    if args.all_formats or args.formats:
        try:
            formats, _ = _resolve_formats(args)
            return formats
        except _SelectionError:
            pass
    return list(_ARTIFACT_FORMATS)


def _state_token(info: ModelInfo, fmt: str, formats: list[str]) -> str:
    reason = _guard_reason(fmt, info.task, info.input_size)
    if reason:
        return "unsupported"
    artifact = _artifact_path(info.path, fmt)
    if not artifact.exists():
        return "missing"
    fresh, _detail = _freshness(info.path, fmt, _default_quantize(fmt), artifact)
    size = _format_mb(_path_size(artifact))
    return f"built {size}" if fresh else f"stale {size}"


def _run_list(args, out: _Output) -> int:
    config = None
    if args.camera or args.configured:
        config = _load_config()
        if config is None:
            raise _SelectionError("--camera/--configured need Config/config.json")
    uses = _selection(args, config)
    if not uses:
        discovered = [_model_info(path) for path in _discover_all()]
        if not discovered:
            out.error("no .pt models found under YoloModels/pytorch")
            return 2
        uses = [_ModelUse(info) for info in discovered]

    formats = _list_formats(args)
    header = (
        f"{'MODEL':28s} {'TASK':8s} {'NC':>3s} {'INPUT':>9s} {'MB':>7s}  "
        + "  ".join(f"{fmt:12s}" for fmt in formats)
    )
    out.info(header)
    out.info("-" * len(header))
    seen: set[str] = set()
    for use in uses:
        info = use.model
        if str(info.path) in seen:
            continue
        seen.add(str(info.path))
        cells = "  ".join(
            f"{_state_token(info, fmt, formats):12s}" for fmt in formats
        )
        out.info(
            f"{info.path.stem[:28]:28s} {info.task:8s} {info.nc:3d} "
            f"{info.input_size[0]}x{info.input_size[1]}  "
            f"{info.size_bytes / (1024 ** 2):7.1f}  {cells}"
        )
    return 0


def _clean_artifacts(out: _Output, dry_run: bool) -> int:
    from iSpy.vision.metadata import metadata_path_for

    pytorch = _pytorch_dir()
    stems = set()
    if pytorch.is_dir():
        for path in pytorch.rglob("*.pt"):
            stems.add(path.stem)

    removed = 0
    for fmt in _ARTIFACT_FORMATS:
        folder = _root() / "YoloModels" / fmt
        if not folder.is_dir():
            continue
        for entry in sorted(folder.iterdir()):
            stem = entry.name
            if fmt == "openvino" and stem.endswith("_openvino_model"):
                stem = stem[: -len("_openvino_model")]
            else:
                stem = entry.stem
            if stem in stems:
                continue
            removed += 1
            sidecar = metadata_path_for(entry)
            if dry_run:
                out.info(f"would remove orphan {_rel_posix(entry)}")
            else:
                if entry.is_dir():
                    shutil.rmtree(entry, ignore_errors=True)
                else:
                    try:
                        entry.unlink()
                    except OSError:
                        pass
                try:
                    sidecar.unlink()
                except OSError:
                    pass
                out.info(f"removed orphan {_rel_posix(entry)}")

    for leftover in (_root() / "YoloModels").rglob("*_rknn_ready.onnx"):
        removed += 1
        if dry_run:
            out.info(f"would remove leftover {_rel_posix(leftover)}")
        else:
            try:
                leftover.unlink()
                out.info(f"removed leftover {_rel_posix(leftover)}")
            except OSError:
                pass

    if removed == 0:
        out.info("no orphaned artifacts found")
    elif dry_run:
        out.info(f"{removed} orphaned artifact(s) would be removed")
    else:
        out.info(f"removed {removed} orphaned artifact(s)")
    return 0


# ---------------------------------------------------------------------------
# Disk / dependencies
# ---------------------------------------------------------------------------


def _estimated_disk_bytes(formats: list[str], jobs: int = 1) -> int:
    """Estimate free space for the planned builds.

    Converter environments own their own floors.  A single job provisions one
    format at a time, so the largest floor is enough; concurrent jobs can
    provision different formats at once, so their floors add up.
    """
    from iSpy.boot.converter_envs import min_free_bytes

    env_floors: list[int] = []
    other = 0
    for fmt in set(formats):
        try:
            floor = int(min_free_bytes(fmt))
        except Exception:
            floor = 0
        if floor:
            env_floors.append(floor)
        else:
            other += _FORMAT_DISK_ESTIMATE.get(fmt, 0)

    if not env_floors:
        env_total = 0
    elif jobs <= 1:
        env_total = max(env_floors)
    else:
        env_total = sum(env_floors)
    return env_total + other


def _disk_check(formats: list[str], out: _Output, jobs: int = 1) -> bool:
    needed = _estimated_disk_bytes(formats, jobs)
    try:
        free = shutil.disk_usage(_root()).free
    except OSError:
        return True
    if free >= needed:
        return True
    out.error(
        f"refusing to start: only {_format_mb(free)} free on the YoloModels "
        f"volume but this plan needs about {_format_mb(needed)} "
        "(override with --no-disk-check)"
    )
    return False


def _install_dependencies(jobs: list[Job], out: _Output) -> None:
    formats = {job.fmt for job in jobs if job.action == "build"}
    if not formats:
        return
    if network_policy.is_offline():
        out.warn(
            "Offline mode: skipping --install-deps - pip needs the internet. "
            "Jobs with missing build dependencies will be skipped."
        )
        return
    from iSpy.boot.backend_deps import ensure_backends

    report = ensure_backends(sorted(formats), auto_install=True)
    for line in report.lines():
        out.info(line)
    if not report.ok:
        for item in report.manual_requirements:
            out.warn(f"{item.backend}: {item.detail or item.status}")
        for item in report.actionable_failures:
            out.error(f"failed to provision {item.backend}: {item.detail or item.status}")


# ---------------------------------------------------------------------------
# Reporting
# ---------------------------------------------------------------------------


def _job_row(job: Job) -> str:
    detail = job.reason
    if job.status == "OK":
        bits = []
        if job.verify == "OK":
            bits.append("verified")
        if job.compare:
            bits.append(job.compare)
        if job.speedup:
            bits.append(f"{job.speedup:.2f}x")
        if job.bench_fps:
            bits.append(f"{job.bench_fps:.1f} FPS")
        detail = "; ".join(bits)
    elif job.status in _BAD_STATUSES:
        detail = f"{job.error_status or 'error'}: {job.error}"
    return (
        f"{job.status:13s} {job.model.path.stem[:24]:24s} "
        f"{job.fmt:9s} {job.seconds:5.0f}s "
        f"{(job.size_bytes / (1024 ** 2)):7.1f} MB  {detail}"
    )


def _summary_counts(jobs: list[Job]) -> dict:
    counts = {"jobs": len(jobs), "ok": 0, "skipped": 0, "failed": 0}
    for job in jobs:
        if job.status == "OK":
            counts["ok"] += 1
        elif job.status == "SKIPPED":
            counts["skipped"] += 1
        elif job.status in _BAD_STATUSES:
            counts["failed"] += 1
    return counts


def _print_summary(jobs: list[Job], out: _Output) -> None:
    counts = _summary_counts(jobs)
    out.info("")
    out.info(
        f"summary: {counts['jobs']} job(s), {counts['ok']} ok, "
        f"{counts['skipped']} skipped, {counts['failed']} failed"
    )
    out.info(
        f"{'STATUS':13s} {'MODEL':24s} {'FORMAT':9s} {'TIME':>6s} "
        f"{'SIZE':>10s}  DETAIL"
    )
    for job in jobs:
        out.info(_job_row(job))

    failures = [job for job in jobs if job.status in _BAD_STATUSES]
    if not failures:
        return
    out.info("")
    out.info("failures:")
    for job in failures:
        hint = _FAILURE_HINTS.get(job.error_status, _FAILURE_HINTS["conversion"])
        out.error(
            f"{job.model.path.name} -> {job.fmt} [{job.status}] "
            f"{job.error_status or 'error'}: {job.error}"
        )
        out.error(f"  hint: {hint}")


def _job_json(job: Job) -> dict:
    return {
        "model": job.model.path.name,
        "source": str(job.model.path),
        "format": job.fmt,
        "status": job.status,
        "artifact": str(job.artifact) if job.artifact else None,
        "size": round(job.size_bytes / (1024 ** 2), 3),
        "size_bytes": job.size_bytes,
        "seconds": round(job.seconds, 2),
        "quantize": bool(job.quantize),
        "verify": job.verify,
        "compare": job.compare,
        "speedup": job.speedup,
        "bench_fps": job.bench_fps,
        "bench_error": job.bench_error,
        "error": job.error,
        "error_status": job.error_status,
        "reason": job.reason,
    }


def _write_json(path: str, jobs: list[Job], exit_code: int, out: _Output) -> None:
    payload = {
        "tool": "ispy-optimize",
        "generated": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "offline": network_policy.is_offline(),
        "jobs": [_job_json(job) for job in jobs],
        "summary": _summary_counts(jobs),
        "exit_code": exit_code,
    }
    text = json.dumps(payload, indent=2)
    if path == "-":
        print(text, flush=True)
        return
    target = Path(path)
    if not target.is_absolute():
        target = _root() / target
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text + "\n", encoding="utf-8")
    out.info(f"wrote {target}")


# ---------------------------------------------------------------------------
# Execution scheduling
# ---------------------------------------------------------------------------


_RKNN_JOB_LOCK = threading.Lock()


def _run_one(job: Job, args, out: _Output) -> Job:
    if job.fmt == "rknn":
        with _RKNN_JOB_LOCK:
            return _execute_job(job, args, out)
    return _execute_job(job, args, out)


def _run_jobs(jobs: list[Job], args, out: _Output) -> list[Job]:
    if not jobs:
        return []
    total = len(jobs)
    counter = {"done": 0}
    counter_lock = threading.Lock()

    def run(job: Job) -> Job:
        if not out.quiet:
            with counter_lock:
                index = counter["done"] + 1
            out.info(
                f"[{index}/{total}] {job.model.path.stem} -> {job.fmt}"
                + (
                    f" (int8, calib={job.dataset_label or job.dataset_arg or 'auto'})"
                    if job.quantize
                    else ""
                )
                + (" ..." if job.action == "build" else " ... skip")
            )
        result = _run_one(job, args, out)
        with counter_lock:
            counter["done"] += 1
            index = counter["done"]
        if not out.quiet:
            if result.status == "OK":
                detail = f"OK {result.seconds:.0f}s {_format_mb(result.size_bytes)}"
                if result.verify == "OK":
                    detail += " verified"
                if result.compare:
                    detail += f" {result.compare}"
                if result.speedup:
                    detail += f" {result.speedup:.2f}x"
                if result.bench_fps:
                    detail += f" {result.bench_fps:.1f} FPS"
            elif result.status == "SKIPPED":
                detail = f"SKIPPED {result.reason}"
            else:
                detail = f"{result.status} {result.error_status}: {result.error}"
            out.info(f"[{index}/{total}] {result.model.path.stem} -> {result.fmt} ... {detail}")
        return result

    results: list[Job] = []
    if args.jobs <= 1:
        for job in jobs:
            result = run(job)
            results.append(result)
            if args.fail_fast and result.status in _BAD_STATUSES:
                break
        return results

    pending = list(jobs)
    with concurrent.futures.ThreadPoolExecutor(max_workers=args.jobs) as pool:
        futures: dict[concurrent.futures.Future, Job] = {}

        def submit_next() -> None:
            while pending and len(futures) < args.jobs:
                job = pending.pop(0)
                futures[pool.submit(run, job)] = job

        submit_next()
        while futures:
            done, _ = concurrent.futures.wait(
                list(futures), return_when=concurrent.futures.FIRST_COMPLETED
            )
            stop = False
            for future in done:
                futures.pop(future, None)
                result = future.result()
                results.append(result)
                if args.fail_fast and result.status in _BAD_STATUSES:
                    stop = True
            if stop:
                for future in futures:
                    future.cancel()
                futures.clear()
                pending.clear()
                break
            submit_next()
    return results


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="ispy-optimize",
        description=(
            "Convert YoloModels/pytorch .pt checkpoints into optimized backend "
            "artifacts (rknn / onnx / openvino / tflite / engine / qnn / hailo, "
            "or tpu passthrough)."
        ),
        epilog=(
            "exit codes: 0 all requested jobs ok or fresh, 1 at least one job "
            "failed, 2 usage/selection error, 130 interrupted"
        ),
    )
    parser.add_argument(
        "models",
        nargs="*",
        metavar="MODEL",
        help="paths, bare names (fuel_detection_v26) or globs; resolved against "
        "YoloModels/pytorch/ then the current directory",
    )
    parser.add_argument(
        "--all",
        action="store_true",
        help="every .pt directly in YoloModels/pytorch (world/ and *.part excluded)",
    )
    parser.add_argument(
        "--camera",
        action="append",
        default=[],
        metavar="NAME",
        help="optimize the model a configured camera uses (repeatable)",
    )
    parser.add_argument(
        "--configured",
        action="store_true",
        help="same as --camera for every model-backed camera",
    )
    parser.add_argument(
        "--exclude",
        dest="excludes",
        action="append",
        default=[],
        metavar="PATTERN",
        help="glob on the filename to exclude (repeatable)",
    )
    parser.add_argument(
        "--skip-defaults",
        action="store_true",
        help="skip the stock _default_*.pt checkpoints",
    )
    parser.add_argument(
        "--download-default",
        action="store_true",
        help="when no .pt exists, download the stock YOLOv8n checkpoint "
        "(Ultralytics, AGPL-3.0) like ispy-bench does",
    )

    parser.add_argument(
        "--format",
        dest="formats",
        action="append",
        default=[],
        metavar="FMT[,FMT...]",
        help="target format(s); 'auto' (default) uses recommend_format(). "
        "Repeatable and comma-separated.",
    )
    parser.add_argument(
        "--all-formats",
        action="store_true",
        help="every backend this machine can build/run (hardware gates from "
        "ispy-bench) plus onnx; never coreml/hailo unless named explicitly",
    )

    quant = parser.add_mutually_exclusive_group()
    quant.add_argument(
        "--quantize",
        dest="quantize",
        action="store_true",
        default=None,
        help="force int8 quantization",
    )
    quant.add_argument(
        "--no-quantize",
        dest="quantize",
        action="store_false",
        help="force float/unquantized builds",
    )
    parser.add_argument(
        "--calib-dataset",
        default=None,
        metavar="PATH",
        help="calibration images for int8 builds (default: camera setting, a "
        "real QuantizeDataset/<name>/ folder, COCO128 on demand, then synthetic)",
    )
    parser.add_argument(
        "--input-size",
        default=None,
        metavar="N|WxH",
        help="conversion input size (default: sidecar, else 640)",
    )
    parser.add_argument(
        "--rknn-target-platform",
        default=None,
        metavar="CHIP",
        help="sets ISPY_RKNN_TARGET_PLATFORM for child processes (rk3588, ...)",
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="rebuild even when a valid cached artifact exists",
    )
    parser.add_argument(
        "--only-missing",
        action="store_true",
        default=True,
        help="skip fresh artifacts (default)",
    )
    parser.add_argument(
        "--jobs",
        type=int,
        default=1,
        metavar="N",
        help="concurrent builds (default 1; rknn always runs serially)",
    )
    parser.add_argument(
        "--fail-fast",
        action="store_true",
        help="stop at the first failure (default: continue)",
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=None,
        metavar="SECONDS",
        help="per-job conversion timeout; the child is killed and marked FAILED",
    )
    parser.add_argument(
        "--install-deps",
        action="store_true",
        help="best-effort install of the build dependencies for planned formats",
    )
    parser.add_argument(
        "--no-disk-check",
        dest="disk_check",
        action="store_false",
        default=True,
        help="skip the free-space pre-flight",
    )

    parser.add_argument(
        "--no-verify",
        dest="verify",
        action="store_false",
        default=True,
        help="do not load each freshly built artifact with GenericYolo",
    )
    parser.add_argument(
        "--remove-bad",
        action="store_true",
        help="delete artifacts that fail --verify",
    )
    parser.add_argument(
        "--compare",
        action="store_true",
        help="surface the verdict/speedup from Outputs/optimized_model_report.json",
    )
    parser.add_argument(
        "--apply",
        action="store_true",
        help="point matching camera configs at the new artifacts (never implied)",
    )
    parser.add_argument(
        "--bench",
        action="store_true",
        help="run a short ispy-bench style predict pass per artifact",
    )
    parser.add_argument(
        "--clean",
        action="store_true",
        help="remove orphaned artifacts (dry-run with --dry-run)",
    )
    parser.add_argument(
        "--list",
        dest="list_models",
        action="store_true",
        help="list discovered models and per-format artifact state, no conversion",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="print the exact job plan and exit 0",
    )
    parser.add_argument(
        "--json",
        dest="json_out",
        nargs="?",
        const=DEFAULT_JSON_PATH,
        default=None,
        metavar="PATH",
        help=f"write machine-readable results (default: {DEFAULT_JSON_PATH}); "
        "'-' prints JSON to stdout",
    )
    parser.add_argument("-v", "--verbose", action="store_true", help="show worker output")
    parser.add_argument(
        "-q", "--quiet", action="store_true", help="only the summary and errors"
    )
    return parser


def _print_usage_and_models(parser: argparse.ArgumentParser, out: _Output) -> None:
    out.info(parser.format_usage().rstrip())
    discovered = _discover_all()
    if discovered:
        out.info("")
        out.info("discovered models:")
        for path in discovered:
            out.info(f"  {path.stem}  ({_rel_posix(path)})")
    else:
        out.info("")
        out.info("no .pt models found under YoloModels/pytorch")
    out.info("")
    out.info("select a model with MODEL, --all, --camera NAME, or --configured")


def _run_plan(args, out: _Output) -> int:
    config = None
    if args.camera or args.configured or args.apply:
        config = _load_config()
        if config is None:
            raise _SelectionError(
                "--camera/--configured/--apply need Config/config.json, which was not found"
            )

    uses = _selection(args, config)
    if not uses and args.download_default:
        from iSpy.validations.benchmarking import _download_default_bench_model

        downloaded = _download_default_bench_model()
        if downloaded:
            uses = [_ModelUse(_model_info(downloaded))]
    if not uses:
        _print_usage_and_models(args._parser, out)
        return 2

    formats, explicit_formats = _resolve_formats(args)
    jobs = _plan_jobs(uses, formats, args, explicit_formats)

    if args.dry_run:
        out.info("plan:")
        for index, job in enumerate(jobs, 1):
            if job.action == "build":
                mode = "int8" if job.quantize else "float"
                calib = f", calib={job.dataset_label or job.dataset_arg or 'auto'}" if job.quantize else ""
                detail = f"build ({mode}{calib})"
            elif job.action == "fresh":
                detail = f"skip (fresh: {job.reason})"
            elif job.action == "passthrough":
                detail = f"skip ({job.reason})"
            else:
                detail = f"skip ({job.reason})"
            out.info(
                f"[{index}/{len(jobs)}] {job.model.path.name} -> {job.fmt} {detail}"
            )
        return 0

    if args.install_deps:
        _install_dependencies(jobs, out)

    build_formats = [job.fmt for job in jobs if job.action == "build"]
    if args.disk_check and build_formats and not _disk_check(
        build_formats, out, int(getattr(args, "jobs", 1) or 1)
    ):
        return 2

    try:
        results = _run_jobs(jobs, args, out)
    except KeyboardInterrupt:
        _terminate_conversion_children()
        _cleanup_partials(0)
        out.error("interrupted - partial summary follows")
        _print_summary(jobs, out)
        if args.apply:
            out.error("--apply skipped because the run was interrupted")
        return 130

    if args.compare:
        _attach_compare(results)
    if args.bench:
        for job in results:
            _bench_job(job)

    applied: list[str] = []
    if args.apply:
        try:
            applied = _apply_results(results, config, args.camera)
        except Exception as exc:
            out.error(f"could not apply results to Config/config.json: {exc}")
            _print_summary(results, out)
            return 1
        if applied:
            out.info(f"applied to camera(s): {', '.join(applied)}")
        else:
            out.info("no matching camera configs were updated")

    _print_summary(results, out)

    exit_code = 1 if any(job.status in _BAD_STATUSES for job in results) else 0
    if args.json_out:
        _write_json(args.json_out, results, exit_code, out)
    return exit_code


def main(argv=None) -> int:
    parser = _build_parser()
    args = parser.parse_args(argv)
    args._parser = parser

    if args.jobs < 1:
        parser.print_usage(sys.stderr)
        print("error: --jobs must be at least 1", file=sys.stderr)
        return 2
    if args.timeout is not None and args.timeout <= 0:
        parser.print_usage(sys.stderr)
        print("error: --timeout must be positive", file=sys.stderr)
        return 2
    if args.rknn_target_platform:
        os.environ["ISPY_RKNN_TARGET_PLATFORM"] = args.rknn_target_platform

    human_stream = sys.stderr if args.json_out == "-" else sys.stdout
    out = _Output(human_stream, quiet=args.quiet, verbose=args.verbose)
    _configure_quiet_logging(
        verbose=args.verbose, quiet=args.quiet, stream=human_stream
    )

    if args.input_size:
        try:
            args.input_size = _parse_input_size(args.input_size)
        except _SelectionError as exc:
            parser.print_usage(sys.stderr)
            out.error(str(exc))
            return 2

    try:
        if args.list_models:
            return _run_list(args, out)
        if args.clean:
            return _clean_artifacts(out, dry_run=args.dry_run)
        with _worker_output(args.verbose):
            return _run_plan(args, out)
    except _SelectionError as exc:
        out.error(str(exc))
        return 2
    except KeyboardInterrupt:
        _terminate_conversion_children()
        _cleanup_partials(0)
        out.error("interrupted")
        return 130


if __name__ == "__main__":
    sys.exit(main())
